SELECT module, CAST(count AS INTEGER) AS count
FROM read_csv_auto('data/boltzgen_data/boltzgen_vhh_glp1_explainer/architecture_counts.csv')
ORDER BY count DESC, module ASC;

SELECT *
FROM read_csv_auto('data/boltzgen_data/boltzgen_vhh_glp1_explainer/source_tables/input_contract.csv', header=true)
ORDER BY CAST(order AS INTEGER) ASC;

SELECT *
FROM read_csv_auto('data/boltzgen_data/boltzgen_vhh_glp1_explainer/source_tables/training_tasks.csv', header=true)
